// UserStats .
// @router /user/stats [GET]
func UserStats(ctx context.Context, c *app.RequestContext) {
	// 从上下文获取用户ID（此前返回硬编码 0）
	userIDVal, exists := c.Get("user_id")
	if !exists {
		c.JSON(consts.StatusUnauthorized, map[string]interface{}{
			"code":    errcode.CodeUnauthorized,
			"message": "用户未登录",
		})
		return
	}
	userID, ok := userIDVal.(uint)
	if !ok {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    errcode.CodeInternal,
			"message": "用户ID类型错误",
		})
		return
	}

	stats, err := getUserService().GetStats(ctx, userID)
	if err != nil {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    errcode.CodeInternal,
			"message": "获取统计失败: " + err.Error(),
		})
		return
	}

	// 配额：用户级覆盖 > 系统默认（0 = 不限）
	quotaUsed := stats.TotalStorage
	quotaLimit := int64(0)
	quotaLimit = getUserService().SystemDefaultStorageQuota(ctx)
	if u, err := getUserService().GetByID(ctx, userID); err == nil && u != nil && u.MaxStorageQuota > 0 {
		quotaLimit = u.MaxStorageQuota
	}

	resp := &usermodel.UserStatsResp{
		Code:    0,
		Message: "获取成功",
		Data: &usermodel.UserStats{
			TotalUploads: int64(stats.TotalUploads),
			TotalSize:    stats.TotalStorage,
			QuotaUsed:    quotaUsed,
			QuotaLimit:   quotaLimit,
		},
	}

	c.JSON(consts.StatusOK, resp)
}

